  "home.workflow.evidence.desc": "ಅಧಿಕೃತ ಕಾನೂನುಗಳು, ನಿಯಮಾವಳಿಗಳು, ಅಧಿಸೂಚನೆಗಳು ಮತ್ತು ಸಾಂಪ್ರದಾಯಿಕ ಜ್ಞಾನ ಮೂಲಗಳ ಸಂಗ್ರಹವನ್ನು ಅನ್ವೇಷಿಸಿ.",
  "home.workflow.assistant.title": "IP-SAKTI AI ಕೇಳಿ",
  "home.workflow.assistant.desc": "IP ಅಥವಾ ನಿಯಮಾವಳಿಗಳ ಕುರಿತು ಸಂಕೀರ್ಣ ಪ್ರಶ್ನೆಗಳನ್ನು ಕೇಳಿ. ಪ್ರತಿಯೊಂದು ಉತ್ತರವೂ ಅಧಿಕೃತ ಸಾಕ್ಷ್ಯವನ್ನು ಆಧರಿಸಿದೆ.",
  "home.howItWorks.title": "IP-SAKTI Sahayak ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ",
  "home.howItWorks.subtitle": "ಪ್ರತಿಯೊಂದು ಶಿಫಾರಸು ಪರಿಶೀಲಿಸಬಹುದಾದ ಮತ್ತು ಕಾನೂನಿನಲ್ಲಿ ಆಧಾರವಾಗಿರುವಂತೆ ನೋಡಿಕೊಳ್ಳುವ 4-ಹಂತದ ಪ್ರಕ್ರಿಯೆ.",
  "home.howItWorks.step1.title": "ನಿಮ್ಮ ಫಾರ್ಮುಲೇಶನ್ ಅಥವಾ ಪ್ರಶ್ನೆಯನ್ನು ನಮೂದಿಸಿ",
  "home.howItWorks.step1.desc": "ಮಾರ್ಗದರ್ಶಿತ ಹಂತಗಳ ಮೂಲಕ ನಿಮ್ಮ ಆಯುರ್ವೇದ ಉತ್ಪನ್ನ ಅಥವಾ ನಿಯಂತ್ರಕ ಪ್ರಶ್ನೆಯನ್ನು ವಿವರಿಸಿ.",
  "home.howItWorks.step2.title": "ನಿಯಮಗಳು ವರ್ಗೀಕರಿಸುತ್ತವೆ. ಸಾಕ್ಷ್ಯಗಳು ಆಧಾರ ಒದಗಿಸುತ್ತವೆ.",
  "home.howItWorks.step2.desc": "ನಿಶ್ಚಿತ ನಿಯಮಗಳು ವರ್ಗೀಕರಣವನ್ನು ಗುರುತಿಸುತ್ತವೆ ಮತ್ತು ಕಾನೂನು ಮೂಲಗಳಿಂದ ಅಧಿಕೃತ ದಾಖಲೆಗಳನ್ನು ತರುತ್ತವೆ.",
  "home.howItWorks.step3.title": "AI ಉಲ್ಲೇಖಗಳೊಂದಿಗೆ ವಿವರಿಸುತ್ತದೆ",
  "home.howItWorks.step3.desc": "ನಿಮಗೆ ಏನು ಅನ್ವಯಿಸುತ್ತದೆ ಎಂಬುದನ್ನು AI ವಿವರಿಸುತ್ತದೆ — ಪ್ರತಿಯೊಂದು ಅಂಶವೂ ಕಾನೂನಿಗೆ ಲಿಂಕ್ ಆಗಿದೆ.",
  "home.howItWorks.step4.title": "ಅರ್ಥಮಾಡಿಕೊಳ್ಳಿ. ಪರಿಶೀಲಿಸಿ. ಕ್ರಮ ಕೈಗೊಳ್ಳಿ.",
  "home.howItWorks.step4.desc": "ಸಾಕ್ಷ್ಯ ಸರಪಳಿಯನ್ನು ಪರಿಶೀಲಿಸಿ, ಮೂಲ ದಾಖಲೆಗಳನ್ನು ನೋಡಿ ಮತ್ತು ಸ್ಪಷ್ಟ ಮುಂದಿನ ಕ್ರಮಗಳನ್ನು ಪಡೆಯಿರಿ.",
  "home.trust.title": "ಕಠಿಣ ಪರಿಶೀಲನೆ ವ್ಯವಸ್ಥೆ",
  "home.trust.subtitle": "ಕಾನೂನು ಅನುಸರಣೆ, ವಿಶ್ವಾಸಾರ್ಹತೆ ಮತ್ತು ಸಾಕ್ಷ್ಯ ಲೆಕ್ಕಪರಿಶೋಧನೆಗಾಗಿ ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ.",
