  "intel.whatSourceDoesNotEstablish": "இது வழங்கப்பட்ட காப்புரிமை அல்லது உரிம ஒப்புதல் அல்ல. இந்த விதியின் இருப்பு நிர்வாக வெற்றியை உறுதிப்படுத்தாது.",
  "intel.noGapsTitle": "முக்கிய சான்றுகள் இடைவெளிகள் எதுவும் கண்டறியப்படவில்லை",
  "intel.noGapsDesc": "இந்த சூத்திரத்திற்கான அனைத்து முக்கிய சட்டப்பூர்வ அளவுருக்களும் குறிப்பிடப்பட்டுள்ளன.",
  "intel.dynamicallyEvaluated": "காப்புரிமை மற்றும் ஆயுஷ் விதிகளுக்கு எதிராக மாறும் வகையில் மதிப்பீடு செய்யப்பட்டது",
  "intel.groundingTraceActive": "அடிப்படை சுவடு செயலில் உள்ளது",
  "intel.groundingTraceDesc": "AI ஊகங்கள் இல்லாமல் உங்கள் சூத்திர அளவுருக்கள் எவ்வாறு விதிகள் மற்றும் சட்டப்பூர்வ மீட்டெடுப்பு வழியாக பாய்ந்தன என்பதைக் கண்காணிக்கவும்.",
  "intel.attachDocsDesc": "வழக்கு ஆதாரங்களை வலுப்படுத்த பகுப்பாய்வு சான்றிதழ் (CoA), ஆராய்ச்சி குறிப்புகள் அல்லது கொள்முதல் ரசீதுகளை இணைக்கவும்.",
  "intel.maxFileSize": "அதிகபட்சம்: 10MB · ஸ்கேன் செய்யப்பட்டு தனிமைப்படுத்தப்பட்டது",
  "intel.supportedFormats": "PDF, DOCX, TXT, CSV, JSON ஆதரிக்கப்படுகிறது",
  "intel.cleanVerified": "சுத்தமானது & சரிபார்க்கப்பட்டது",
  "intel.quarantined": "தனிமைப்படுத்தப்பட்டது",
  "intel.securityPrinciple": "பாதுகாப்புக் கொள்கை:",
  "intel.securityPrincipleDesc": "அனைத்து ஆவண உள்ளடக்கங்களும் நம்பத்தகாத சமர்ப்பிப்புகளாகக் கருதப்படுகின்றன. பிரித்தெடுக்கப்பட்ட அளவுருக்கள் சட்ட விதிகளை மீற முடியாது.",
  "intel.provenanceTracer": "மூல சுவடு காணிப்பான் (Provenance)",
  "intel.timeMachineDesc": "வரலாற்று திருத்தங்கள், வர்த்தமானி அறிவிப்புகள் மற்றும் சட்ட விதிகளின் பரிணாமத்தை தணிக்கை செய்யவும்.",
  "intel.selectFramework": "கட்டமைப்பைத் தேர்ந்தெடுக்கவும்:",
