  "home.workflow.analyze.desc": "फॉर्मूलेशन दर्ज करें और साक्ष्य-आधारित वर्गीकरण, लागू नियम व IP रूपरेखा प्राप्त करें।",
  "home.workflow.protect.title": "नवाचार का संरक्षण करें",
  "home.workflow.protect.desc": "अपने फॉर्मूले, ब्रांड, डिजाइन या पारंपरिक ज्ञान को प्रासंगिक IP मार्गों से जोड़ें।",
  "home.workflow.regulations.title": "विनियम जांचें",
  "home.workflow.regulations.desc": "जानें कि आपके उत्पाद पर कौन से आयुष, FSSAI, औषधि व प्रसाधन नियम लागू होते हैं।",
  "home.workflow.evidence.title": "साक्ष्य खोजें",
  "home.workflow.evidence.desc": "अधिकृत कानूनों, नियमों, संधियों और पारंपरिक ज्ञान स्रोतों का संग्रह देखें।",
  "home.workflow.assistant.title": "IP-SAKTI AI से पूछें",
  "home.workflow.assistant.desc": "बौद्धिक संपदा या नियमों पर प्रश्न पूछें। प्रत्येक उत्तर आधिकारिक साक्ष्यों पर आधारित है।",
  "home.howItWorks.title": "IP-SAKTI Sahayak कैसे कार्य करता है",
  "home.howItWorks.subtitle": "एक संरचित 4-चरणीय प्रक्रिया जो सुनिश्चित करती है कि प्रत्येक सिफारिश सत्यापन योग्य हो।",
  "home.howItWorks.step1.title": "फॉर्मूलेशन या प्रश्न दर्ज करें",
  "home.howItWorks.step1.desc": "अपने आयुर्वेदिक उत्पाद या विनियामक प्रश्न को निर्देशित कार्यप्रवाह में दर्ज करें।",
  "home.howItWorks.step2.title": "नियम वर्गीकृत करते हैं, साक्ष्य आधार देते हैं",
  "home.howItWorks.step2.desc": "नियत नियम वर्गीकरण पहचानते हैं और विधिक संग्रह से अधिकृत स्रोत लाते हैं।",
  "home.howItWorks.step3.title": "AI संदर्भों के साथ समझाता है",
  "home.howItWorks.step3.desc": "AI व्याख्या करता है कि आप पर क्या लागू होता है — प्रत्येक दावा कानून से जुड़ा होता है।",
  "home.howItWorks.step4.title": "समझें, सत्यापित करें, कार्यवाही करें",
  "home.howItWorks.step4.desc": "साक्ष्य श्रृंखला की समीक्षा करें, मूल दस्तावेजों को देखें और स्पष्ट कार्य योजना पाएं।",
  "home.trust.title": "अंतर्निहित कठोर सत्यापन",
  "home.trust.subtitle": "अनुपालन, कानूनी सुरक्षा और साक्ष्य लेखापरीक्षा के लिए तैयार।",
  "home.trust.point1": "प्रत्येक उत्तर विशिष्ट कानून, धारा और प्राधिकारी को उद्धृत करता है",
  "home.trust.point2": "स्रोत संस्करणित हैं — आप देख सकते हैं कि नियम कब बदला",
  "home.trust.point3": "साक्ष्य अपर्याप्त होने पर AI अटकलें लगाने से बचता है",
  "home.trust.point4": "वर्गीकरण नियत नियमों द्वारा होता है, अनुमान से नहीं",
  "home.trust.point5": "प्रॉम्प्ट इंजेक्शन सुरक्षा दस्तावेज़ में हेरफेर रोकती है",
  "home.trust.point6": "दस्तावेज़ सुरक्षित रूप से केवल हस्ताक्षरित लिंक से सुलभ हैं",
